program:
procedure VetVaccinationReminders {
  about "Remind each pet owner about their vaccination"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger every day at 08:00

  let all = fetch Pets
  let due = filter all where vaccine_due == today() + 1 day and status == "active"
  for each r in due up to 30 {
    let m = draft sms to r.phone: "Hi {r.owner}, a reminder from the clinic: your vaccination is tomorrow."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

