procedure VetOverdueFollowUp {
  about "Follow up with pet owners marked overdue"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger every tuesday at 08:00

  let all = fetch Pets
  let recent = filter all where status == "overdue" and days_between(vaccine_due, today()) <= 3 and days_between(vaccine_due, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no overdue pet owners"
  }
  notify owner "Overdue pet owners to follow up: {n}"
  for each r in recent up to 40 {
    let m = draft sms to r.phone: "Hi {r.owner}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
    update r set status = "contacted"
  }
}

