procedure VetWinBack {
  about "Nudge pet owners whose vaccination was long ago"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger every wednesday at 08:30

  let all = fetch Pets
  let old = filter all where days_between(vaccine_due, today()) >= 30 and status != "inactive"
  let oldest = sort old by vaccine_due first 15
  for each r in oldest up to 15 {
    let m = draft sms to r.phone: "Hi {r.owner}, it's been a while! We'd love to see you again at the clinic."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

