procedure VetLateBalance {
  about "Remind late pet owners; escalate very late ones"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger every thursday at 18:00

  let all = fetch Pets
  let late = filter all where balance > $0.00 and days_between(vaccine_due, today()) > 7
  for each r in late up to 30 {
    if days_between(r.vaccine_due, today()) > 21 {
      notify owner "{r.owner} is very late ({r.balance}). Please call."
    } else {
      let m = draft sms to r.phone: "Hello {r.owner default 'there'}, our records show a balance of {r.balance}. Questions? Just reply."
      let ok = request approval of m from owner timeout 12 hours else skip
      send ok
    }
  }
}

