procedure VetOutreachCampaign {
  about "On request, contact recent inactive pet owners"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Pets
  let targets = filter all where status == "inactive" and days_between(vaccine_due, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft sms to r.phone: "Hi {r.owner}, come back to the clinic! Use code COMEBACK15 on your next visit."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
  }
}

