procedure FloristFailedFollowUp {
  about "Follow up with customers marked failed"
  policy FloristPolicy
  sheet Deliveries "Deliveries" { customer: Text, email: Email, deliver_on: Date, status: Text, price: Money, card_message: Text private }
  trigger every day at 10:00

  let all = fetch Deliveries
  let recent = filter all where status == "failed" and days_between(deliver_on, today()) <= 2 and days_between(deliver_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no failed customers"
  }
  notify owner "Failed customers to follow up: {n}"
  for each r in recent up to 20 {
    let m = draft email to r.email subject "Let's find a new time": "Hi {r.customer}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 12 hours else skip
    send ok
    update r set status = "contacted"
  }
}

