procedure FloristWinBack {
  about "Nudge customers whose delivery was long ago"
  policy FloristPolicy
  sheet Deliveries "Deliveries" { customer: Text, email: Email, deliver_on: Date, status: Text, price: Money, card_message: Text private }
  trigger every friday at 08:30

  let all = fetch Deliveries
  let old = filter all where days_between(deliver_on, today()) >= 42 and status != "cancelled"
  let oldest = sort old by deliver_on first 15
  for each r in oldest up to 15 {
