policy:
policy FloristStockPolicy {
  allow read Flowers(flower, stems, minimum, reorder_qty, grower, unit_cost)
  allow supplier Flowers.grower
  limit order $100 per action
  limit order $300 per day
}

program:
procedure FloristReorder {
  about "Reorder flowers below their minimum"
  policy FloristStockPolicy
  sheet Flowers "Flowers" { flower: Text, stems: Number, minimum: Number, reorder_qty: Number, grower: Text, unit_cost: Money }
  trigger every day at 08:00

  let all = fetch Flowers
  let low = filter all where stems < minimum
  for each i in low up to 3 {
    let cost = i.reorder_qty * i.unit_cost
    if cost > $100.00 {
      notify owner "Reorder of {i.flower} would cost {cost}, over the $100 limit."
      skip
    }
    order "{i.reorder_qty} x {i.flower}" from i.grower cost cost, ask owner first timeout 6 hours else skip
    log "ordered {i.flower}"
  }
}

