procedure PlumbingNoAccessFollowUp {
  about "Follow up with customers marked no-access"
  policy PlumbingPolicy
  sheet Calls "Calls" { customer: Text, phone: Phone, visit_at: DateTime, status: Text, invoice: Money, alarm_code: Text private }
  trigger every monday at 17:30

  let all = fetch Calls
  let recent = filter all where status == "no-access" and days_between(visit_at, today()) <= 1 and days_between(visit_at, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no no-access customers"
  }
  notify owner "No-access customers to follow up: {n}"
  for each r in recent up to 30 {
    let m = draft sms to r.phone: "Hi {r.customer}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
    update r set status = "followed-up"
  }
}

