procedure PlumbingConfirmNewServiceCall {
  about "Confirm a new service call and add it to the calendar"
  policy PlumbingPolicy
  sheet Calls "Calls" { customer: Text, phone: Phone, visit_at: DateTime, status: Text, invoice: Money, alarm_code: Text private }
  calendar Vans "Vans"
  trigger when new row r in Calls

  if r.visit_at < now() + 2 hours {
    notify owner "Short-notice service call for {r.customer} at {r.visit_at}. Please handle it."
    stop "short notice goes to owner"
  }
  let m = draft sms to r.phone: "Hi {r.customer}, your service call with the company is confirmed for {r.visit_at}."
  let ok = request approval of m from owner timeout 1 day else stop "confirmation not approved"
  send ok
  let ev = book Vans { title: "{r.customer}", at: r.visit_at, length: 90 minutes }
  update r set status = "confirmed"
}

