procedure PhotostudioDeliveredFollowUp {
  about "Follow up with clients marked delivered"
  policy PhotostudioPolicy
  sheet Shoots "Shoots" { client: Text, email: Email, shoot_on: Date, status: Text, deposit: Money, venue_notes: Text private }
  trigger every day at 10:00

  let all = fetch Shoots
  let recent = filter all where status == "delivered" and days_between(shoot_on, today()) <= 1 and days_between(shoot_on, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no delivered clients"
  }
  notify owner "Delivered clients to follow up: {n}"
  for each r in recent up to 30 {
    let m = draft email to r.email subject "Let's find a new time": "Hi {r.client default 'there'}, we're sorry we missed you. Reply to set up a new time."
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
    update r set status = "contacted"
  }
}

