procedure PhotostudioOutreachCampaign {
  about "On request, contact recent cancelled clients"
  policy PhotostudioPolicy
  sheet Shoots "Shoots" { client: Text, email: Email, shoot_on: Date, status: Text, deposit: Money, venue_notes: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Shoots
  let targets = filter all where status == "cancelled" and days_between(shoot_on, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 100 {
    let m = draft email to r.email subject "We'd love to see you": "Hi {r.client default 'there'}, come back to the studio! Use code RETURN20 on your next visit."
    let ok = request approval of m from owner timeout 1 day else skip
    send ok
  }
}

